package com.example;import org.springframework.context.annotation.AnnotationConfigApplicationContext;public class MainApp {public static void main(String[] args){try(var ctx=new AnnotationConfigApplicationContext(AppConfig.class)){var svc=ctx.getBean(EmployeeService.class);System.out.println("Container-created bean: "+ctx.containsBean("employeeService"));System.out.println("Same singleton: "+(svc==ctx.getBean("employeeService")));svc.addEmployee(new Employee(101,"Gourav","Development",45000));svc.addEmployee(new Employee(102,"Neha","Testing",38000));svc.listEmployees().forEach(System.out::println);System.out.println("Total salary: "+svc.totalSalary());}}}
